import * as E from '../../src/empire/state.js';import {renderApp} from '../../src/empire/views.js';import {validateSnapshot} from '../../src/unified/save.js';
let s;const app=document.querySelector('#app'),status=document.querySelector('#qa-status');
function render(){app.innerHTML=renderApp(s,{page:'contracts'});app.querySelectorAll('[data-nav],[data-fullscreen]').forEach(b=>b.disabled=true);}
function reset(r){s=E.newState(0);s.rebirth=r;s.xp=E.levelXP(45);s.money=10n**30n;s.copper[0]=10n**15n;s.components.parts=1000;s.run.earned=10n**30n;render();status.textContent='Disposable R'+r+' workshop ready.';}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;try{const qa=b.dataset.qa,action=b.dataset.action;if(qa==='advanced'||qa==='difficult'){reset(qa==='advanced'?5:8);return;}if(qa==='recover'){s.inventory[1]=1;const a=E.begin(s,1);while(a.status!=='complete'){a.status='active';E.stagePass(a,1);}E.reward(s,a,()=>.5);}if(qa==='sell')E.sell(s,25000000000n);if(qa==='craft')E.craft(s,'wire');if(qa==='smelt'){const j=E.startFurnace(s,1000000n,0);E.collectFurnace(s,j.id,j.ends);}if(qa==='reload')s=validateSnapshot(E.decode(E.encode(s)));if(action==='accept-contract')E.acceptContract(s,E.availableContracts(s).find(c=>c.id===b.dataset.id));if(action==='claim-contract')E.claimContract(s,b.dataset.id);render();status.textContent='Saved fixture only · Advanced claimed '+s.run.advancedContracts+' · Difficult claimed '+s.run.difficultContracts+' · '+s.contracts.filter(c=>!c.claimed).length+'/3 active';}catch(error){status.textContent=error.message;}});reset(8);
